# ---------- calendar cross-check for month arithmetic ----------
import calendar

checked = 0
for year in (1, 4, 100, 400, 1900, 2000, 2023, 2024, 9998):
    for month in range(1, 13):
        for day in range(1, calendar.monthrange(year, month)[1] + 1):
            for months in (-25, -13, -12, -1, 0, 1, 11, 12, 13, 25, 100, 1000):
                moment = datetime(year, month, day, 12, 34, 56)
                total_months = (month - 1) + months
                target_year = year + total_months // 12
                target_month = total_months % 12 + 1
                if 1 <= target_year <= 9999:
                    target_day = min(day, calendar.monthrange(target_year, target_month)[1])
                    expected = datetime(target_year, target_month, target_day, 12, 34, 56)
                    got = add(moment, Duration(months=months))
                else:
                    try:
                        add(moment, Duration(months=months))
                    except ValueError:
                        pass
                    else:
                        raise AssertionError((moment, months))
                    checked += 1
                    continue
                assert got == expected, (moment, months, got, expected)
                checked += 1
print("calendar cross-check:", checked, "cases OK")

